  moves: number[]
  winner: 'you' | 'claude' | 'draw' | null
  /** The four cells of the winning line. */
  winningLine: number[] | null
  level: Level
  /** Who moved first this game. The loser starts the next one. */
  starter: 'you' | 'claude'
